class Solution {
public:
    vector<int> sortByBits(vector<int>& arr) {
        sort(arr.begin(),arr.end(),[](const int &a,const int &b){
            int cnta=__builtin_popcount(a);
            int cntb=__builtin_popcount(b);
            return cnta==cntb?a<b:cnta<cntb;
        });
        return arr;
    }
};

